{-| @Backend.Runtime.Host.Time — the calendar and an instant rendered with a pattern, as `Pudu.Eval.Clock` answers it under the fixed English locale. -}
module Pudu.Backend.Runtime.Host.Time (hostTimeParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostTimeParts :: [(Text, [Text], [Text])]
hostTimeParts =
  [ ("host_calendar", ["host_optional", "host_grow", "host_time"],
      [ "/* Text being built. */"
      , "typedef struct { char *bytes; size_t held, room; } pudu_host_words;"
      , "PUDU_OPTIONAL static inline void pudu_host_words_put(pudu_host_words *out, const char *bytes, size_t count) {"
      , "  if (out->room - out->held < count) {"
      , "    while (out->room - out->held < count) out->room = out->room < 64 ? 64 : out->room * 2;"
      , "    out->bytes = pudu_host_grow(out->bytes, out->room);"
      , "  }"
      , "  if (count != 0) memcpy(out->bytes + out->held, bytes, count);"
      , "  out->held += count;"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_words_fill(pudu_host_words *out, char with, int64_t count) {"
      , "  for (; count > 0; --count) pudu_host_words_put(out, &with, 1);"
      , "}"
      , "PUDU_OPTIONAL static inline int64_t pudu_host_floor_div(int64_t value, int64_t by) {"
      , "  int64_t quotient = value / by;"
      , "  return value % by != 0 && (value < 0) != (by < 0) ? quotient - 1 : quotient;"
      , "}"
      , "PUDU_OPTIONAL static inline int64_t pudu_host_floor_mod(int64_t value, int64_t by) { return value - pudu_host_floor_div(value, by) * by; }"
      , "/* Days since the start of 1970 for a date of the proleptic Gregorian calendar. */"
      , "PUDU_OPTIONAL static inline int64_t pudu_host_days_from_civil(int64_t year, int month, int day) {"
      , "  int64_t era, shifted = month <= 2 ? year - 1 : year;"
      , "  int64_t of_era, day_of_year, day_of_era;"
      , "  era = pudu_host_floor_div(shifted, 400);"
      , "  of_era = shifted - era * 400;"
      , "  day_of_year = (153 * (month + (month > 2 ? -3 : 9)) + 2) / 5 + day - 1;"
      , "  day_of_era = of_era * 365 + of_era / 4 - of_era / 100 + day_of_year;"
      , "  return era * 146097 + day_of_era - 719468;"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_host_civil_from_days(int64_t days, int64_t *year, int *month, int *day) {"
      , "  int64_t shifted = days + 719468, era = pudu_host_floor_div(shifted, 146097);"
      , "  int64_t day_of_era = shifted - era * 146097;"
      , "  int64_t of_era = (day_of_era - day_of_era / 1460 + day_of_era / 36524 - day_of_era / 146096) / 365;"
      , "  int64_t day_of_year = day_of_era - (365 * of_era + of_era / 4 - of_era / 100);"
      , "  int64_t turned = (5 * day_of_year + 2) / 153;"
      , "  *day = (int)(day_of_year - (153 * turned + 2) / 5 + 1);"
      , "  *month = (int)(turned < 10 ? turned + 3 : turned - 9);"
      , "  *year = of_era + era * 400 + (*month <= 2 ? 1 : 0);"
      , "}"
      , "PUDU_OPTIONAL static inline int pudu_host_leap_year(int64_t year) {"
      , "  return pudu_host_floor_mod(year, 4) == 0 && (pudu_host_floor_mod(year, 100) != 0 || pudu_host_floor_mod(year, 400) == 0);"
      , "}"
      , "PUDU_OPTIONAL static inline int pudu_host_month_length(int64_t year, int month) {"
      , "  static const int lengths[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};"
      , "  return month == 2 && pudu_host_leap_year(year) ? 29 : lengths[month - 1];"
      , "}"
      , "/* The year and week of the week-numbered calendar a day falls in, weeks starting on Monday. */"
      , "PUDU_OPTIONAL static inline void pudu_host_week_date(int64_t days, int64_t *week_year, int *week) {"
      , "  int64_t weekday = pudu_host_floor_mod(days + 3, 7) + 1, thursday = days + 4 - weekday;"
      , "  int month, day;"
      , "  pudu_host_civil_from_days(thursday, week_year, &month, &day);"
      , "  *week = (int)((thursday - pudu_host_days_from_civil(*week_year, 1, 1)) / 7 + 1);"
      , "}"
      , "PUDU_OPTIONAL static const char *const pudu_host_weekdays[] = {\"Sunday\", \"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\"};"
      , "PUDU_OPTIONAL static const char *const pudu_host_months[] = {\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"};"
      ])
  , ("host_format_time", ["host_calendar", "host_done", "text_copy", "integer_value", "magnitude"],
      [ "/* How one specifier is padded: whether at all, to what width, with what. */"
      , "typedef struct { int mode; char with; int widthed; int64_t width; } pudu_host_padding;"
      , "typedef struct { int padded; int64_t width; char with; } pudu_host_pad;"
      , "static pudu_host_pad pudu_host_pad_of(const pudu_host_padding *asked, int truncates, int by_default, int64_t width, char with) {"
      , "  pudu_host_pad pad;"
      , "  pad.with = asked->mode == 1 ? asked->with : asked->mode == 2 ? ' ' : with;"
      , "  pad.width = !asked->widthed ? width : asked->mode == 2 || truncates ? asked->width : asked->width > width ? asked->width : width;"
      , "  pad.padded = asked->widthed ? 1 : asked->mode == 0 ? by_default : asked->mode == 1;"
      , "  return pad;"
      , "}"
      , "static void pudu_host_put_text(pudu_host_words *out, const pudu_host_padding *asked, const char *text, size_t length) {"
      , "  pudu_host_pad pad = pudu_host_pad_of(asked, 0, 0, 1, ' ');"
      , "  if (pad.padded) pudu_host_words_fill(out, pad.with, pad.width - (int64_t)length);"
      , "  pudu_host_words_put(out, text, length);"
      , "}"
      , "static void pudu_host_put_number(pudu_host_words *out, const pudu_host_padding *asked, int by_default, int64_t width, char with, int64_t value) {"
      , "  pudu_host_pad pad = pudu_host_pad_of(asked, 0, by_default, width, with);"
      , "  char digits[32];"
      , "  int length;"
      , "  uint64_t size = value < 0 ? (uint64_t)0 - (uint64_t)value : (uint64_t)value;"
      , "  if (value < 0 && pad.padded) pudu_host_words_put(out, \"-\", 1);"
      , "  length = snprintf(digits, sizeof digits, value < 0 && !pad.padded ? \"-%llu\" : \"%llu\", (unsigned long long)size);"
      , "  if (pad.padded) pudu_host_words_fill(out, pad.with, pad.width - (int64_t)length);"
      , "  pudu_host_words_put(out, digits, (size_t)length);"
      , "}"
      , "typedef struct { int64_t days, year, seconds; int month, day, hour, minute, second, millis; } pudu_host_moment;"
      , "static void pudu_host_format_into(pudu_host_words *out, const unsigned char *pattern, size_t length, const pudu_host_moment *at);"
      , "static void pudu_host_put_pattern(pudu_host_words *out, const pudu_host_padding *asked, const char *pattern, const pudu_host_moment *at) {"
      , "  pudu_host_words inner = {NULL, 0, 0};"
      , "  pudu_host_format_into(&inner, (const unsigned char *)pattern, strlen(pattern), at);"
      , "  pudu_host_put_text(out, asked, inner.bytes, inner.held);"
      , "  free(inner.bytes);"
      , "}"
      , "static void pudu_host_put_fraction(pudu_host_words *out, const pudu_host_padding *asked, int by_default, int dotted, int millis) {"
      , "  pudu_host_pad pad = pudu_host_pad_of(asked, 1, by_default, 12, '0');"
      , "  char digits[4];"
      , "  int64_t held = 0;"
      , "  if (millis != 0) {"
      , "    (void)snprintf(digits, sizeof digits, \"%03d\", millis);"
      , "    held = 3;"
      , "    while (held > 0 && digits[held - 1] == '0') held -= 1;"
      , "  }"
      , "  if (pad.padded && pad.width < held) held = pad.width < 0 ? 0 : pad.width;"
      , "  if (dotted && held == 0 && !(pad.padded && pad.width > 0)) return;"
      , "  if (dotted) pudu_host_words_put(out, \".\", 1);"
      , "  pudu_host_words_put(out, digits, (size_t)held);"
      , "  if (pad.padded) pudu_host_words_fill(out, pad.with, pad.width - held);"
      , "}"
      , "static void pudu_host_put_zone(pudu_host_words *out, const pudu_host_padding *asked, int colon) {"
      , "  pudu_host_pad pad = pudu_host_pad_of(asked, 0, 1, colon ? 5 : 4, '0');"
      , "  pudu_host_words_put(out, \"+\", 1);"
      , "  if (colon) {"
      , "    if (pad.padded) pudu_host_words_fill(out, pad.with, (pad.width - 3 < 0 ? 0 : pad.width - 3) - 1);"
      , "    pudu_host_words_put(out, \"0:00\", 4);"
      , "  } else {"
      , "    if (pad.padded) pudu_host_words_fill(out, pad.with, pad.width - 1);"
      , "    pudu_host_words_put(out, \"0\", 1);"
      , "  }"
      , "}"
      , "static void pudu_host_format_one(pudu_host_words *out, char specifier, int alternate, const pudu_host_padding *asked, const pudu_host_moment *at) {"
      , "  int64_t year_day = at->days - pudu_host_days_from_civil(at->year, 1, 1) + 1;"
      , "  int64_t sunday = pudu_host_floor_mod(at->days + 4, 7), monday = pudu_host_floor_mod(at->days + 3, 7) + 1;"
      , "  int64_t julian = at->days + 40587, week_year;"
      , "  int week, half = (at->hour + 11) % 12 + 1;"
      , "  const char *name;"
      , "  pudu_host_week_date(at->days, &week_year, &week);"
      , "  switch (specifier) {"
      , "    case '%': pudu_host_put_text(out, asked, \"%\", 1); break;"
      , "    case 't': pudu_host_words_put(out, \"\\t\", 1); break;"
      , "    case 'n': pudu_host_words_put(out, \"\\n\", 1); break;"
      , "    case 'Y': pudu_host_put_number(out, asked, 0, 4, '0', at->year); break;"
      , "    case 'y': pudu_host_put_number(out, asked, 1, 2, '0', pudu_host_floor_mod(at->year, 100)); break;"
      , "    case 'C': pudu_host_put_number(out, asked, 0, 2, '0', pudu_host_floor_div(at->year, 100)); break;"
      , "    case 'B': name = pudu_host_months[at->month - 1]; pudu_host_put_text(out, asked, name, strlen(name)); break;"
      , "    case 'b': case 'h': pudu_host_put_text(out, asked, pudu_host_months[at->month - 1], 3); break;"
      , "    case 'm': pudu_host_put_number(out, asked, 1, 2, '0', at->month); break;"
      , "    case 'd': pudu_host_put_number(out, asked, 1, 2, '0', at->day); break;"
      , "    case 'e': pudu_host_put_number(out, asked, 1, 2, ' ', at->day); break;"
      , "    case 'j': pudu_host_put_number(out, asked, 1, 3, '0', year_day); break;"
      , "    case 'G': pudu_host_put_number(out, asked, 0, 4, '0', week_year); break;"
      , "    case 'g': pudu_host_put_number(out, asked, 1, 2, '0', pudu_host_floor_mod(week_year, 100)); break;"
      , "    case 'f': pudu_host_put_number(out, asked, 0, 2, '0', pudu_host_floor_div(week_year, 100)); break;"
      , "    case 'V': pudu_host_put_number(out, asked, 1, 2, '0', week); break;"
      , "    case 'u': pudu_host_put_number(out, asked, 1, 1, '0', monday); break;"
      , "    case 'w': pudu_host_put_number(out, asked, 1, 1, '0', sunday); break;"
      , "    case 'a': pudu_host_put_text(out, asked, pudu_host_weekdays[sunday], 3); break;"
      , "    case 'A': name = pudu_host_weekdays[sunday]; pudu_host_put_text(out, asked, name, strlen(name)); break;"
      , "    case 'U': pudu_host_put_number(out, asked, 1, 2, '0', pudu_host_floor_div(julian + 3, 7) - pudu_host_floor_div(julian + 3 - year_day, 7)); break;"
      , "    case 'W': pudu_host_put_number(out, asked, 1, 2, '0', pudu_host_floor_div(julian + 2, 7) - pudu_host_floor_div(julian + 2 - year_day, 7)); break;"
      , "    case 'D': case 'x': pudu_host_put_pattern(out, asked, \"%m/%d/%y\", at); break;"
      , "    case 'F': pudu_host_put_pattern(out, asked, \"%Y-%m-%d\", at); break;"
      , "    case 'c': pudu_host_put_pattern(out, asked, \"%a %b %e %H:%M:%S %Z %Y\", at); break;"
      , "    case 'R': pudu_host_put_pattern(out, asked, \"%H:%M\", at); break;"
      , "    case 'T': case 'X': pudu_host_put_pattern(out, asked, \"%H:%M:%S\", at); break;"
      , "    case 'r': pudu_host_put_pattern(out, asked, \"%I:%M:%S %p\", at); break;"
      , "    case 'p': pudu_host_put_text(out, asked, at->hour < 12 ? \"AM\" : \"PM\", 2); break;"
      , "    case 'P': pudu_host_put_text(out, asked, at->hour < 12 ? \"am\" : \"pm\", 2); break;"
      , "    case 'H': pudu_host_put_number(out, asked, 1, 2, '0', at->hour); break;"
      , "    case 'I': pudu_host_put_number(out, asked, 1, 2, '0', half); break;"
      , "    case 'k': pudu_host_put_number(out, asked, 1, 2, ' ', at->hour); break;"
      , "    case 'l': pudu_host_put_number(out, asked, 1, 2, ' ', half); break;"
      , "    case 'M': pudu_host_put_number(out, asked, 1, 2, '0', at->minute); break;"
      , "    case 'S': pudu_host_put_number(out, asked, 1, 2, '0', at->second); break;"
      , "    case 'q': pudu_host_put_fraction(out, asked, 1, 0, at->millis); break;"
      , "    case 'Q': pudu_host_put_fraction(out, asked, 0, 1, at->millis); break;"
      , "    case 's': pudu_host_put_number(out, asked, 1, 1, '0', at->seconds); break;"
      , "    case 'z': pudu_host_put_zone(out, asked, alternate); break;"
      , "    case 'Z': pudu_host_put_text(out, asked, \"UTC\", 3); break;"
      , "    default: break;"
      , "  }"
      , "}"
      , "static void pudu_host_format_into(pudu_host_words *out, const unsigned char *pattern, size_t length, const pudu_host_moment *at) {"
      , "  size_t index = 0;"
      , "  while (index < length) {"
      , "    pudu_host_padding asked = {0, 0, 0, 0};"
      , "    size_t next = index + 1, from;"
      , "    int recase = 0, alternate = 0;"
      , "    if (pattern[index] != '%') { pudu_host_words_put(out, (const char *)pattern + index, 1); index += 1; continue; }"
      , "    if (next < length) {"
      , "      switch (pattern[next]) {"
      , "        case '_': asked.mode = 1; asked.with = ' '; next += 1; break;"
      , "        case '-': asked.mode = 2; next += 1; break;"
      , "        case '0': asked.mode = 1; asked.with = '0'; next += 1; break;"
      , "        case '^': recase = 1; next += 1; break;"
      , "        case '#': recase = 2; next += 1; break;"
      , "        default: break;"
      , "      }"
      , "    }"
      , "    while (next < length && pattern[next] >= '0' && pattern[next] <= '9') {"
      , "      asked.widthed = 1;"
      , "      if (asked.width < 1000000) asked.width = asked.width * 10 + (pattern[next] - '0');"
      , "      next += 1;"
      , "    }"
      , "    if (next < length && pattern[next] == 'E') { alternate = 1; next += 1; }"
      , "    if (next >= length) { pudu_host_words_put(out, \"%\", 1); index += 1; continue; }"
      , "    from = out->held;"
      , "    if (pattern[next] < 0x80) pudu_host_format_one(out, (char)pattern[next], alternate, &asked, at);"
      , "    next += 1;"
      , "    while (next < length && (pattern[next] & 0xC0) == 0x80) next += 1;"
      , "    for (; recase != 0 && from < out->held; ++from) {"
      , "      char letter = out->bytes[from];"
      , "      if (recase == 1 && letter >= 'a' && letter <= 'z') out->bytes[from] = (char)(letter - 32);"
      , "      if (recase == 2 && letter >= 'A' && letter <= 'Z') out->bytes[from] = (char)(letter + 32);"
      , "    }"
      , "    index = next;"
      , "  }"
      , "}"
      , "/* An instant in milliseconds since the start of 1970, rendered with a pattern"
      , "   in the zone named: `local` is the machine's present offset, anything else none. */"
      , "static pudu_text pudu_host_format_time(pudu_text pattern, pudu_int instant, pudu_text zone) {"
      , "  const int64_t day_millis = 86400000;"
      , "  uint64_t magnitude = pudu_magnitude(instant);"
      , "  int64_t days = (int64_t)(magnitude / (uint64_t)day_millis);"
      , "  int64_t of_day = (int64_t)(magnitude % (uint64_t)day_millis), carry;"
      , "  pudu_host_moment at;"
      , "  pudu_host_words out = {NULL, 0, 0};"
      , "  pudu_text made;"
      , "  /* Apply the sign and zone to bounded day components. */"
      , "  if (instant.negative) { days = -days; of_day = -of_day; }"
      , "  if (zone.length == 5 && memcmp(zone.bytes, \"local\", 5) == 0) {"
      , "    time_t now = time(NULL);"
      , "    struct tm local;"
      , "    (void)localtime_r(&now, &local);"
      , "    of_day += (int64_t)(local.tm_gmtoff / 60) * 60000;"
      , "  }"
      , "  carry = pudu_host_floor_div(of_day, day_millis);"
      , "  at.days = days + carry;"
      , "  of_day -= carry * day_millis;"
      , "  at.seconds = at.days * 86400 + of_day / 1000;"
      , "  pudu_host_civil_from_days(at.days, &at.year, &at.month, &at.day);"
      , "  at.hour = (int)(of_day / 3600000);"
      , "  at.minute = (int)(of_day / 60000 % 60);"
      , "  at.second = (int)(of_day / 1000 % 60);"
      , "  at.millis = (int)(of_day % 1000);"
      , "  pudu_host_format_into(&out, pattern.bytes, pattern.length, &at);"
      , "  made = pudu_text_copy(out.bytes == NULL ? \"\" : out.bytes, out.held);"
      , "  free(out.bytes);"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  ]
